//    NOTE: bits correspond to the integer value of 'tci'.
//    tci is stored in memory as big-endian.
//    The value is obtained by reading bytes from memory and swapping them.
inline void ietf::pcp_Set(ietf::Vlanhdr& parent, u8 rhs) {
    u16 t1    = u16(0x07) << 13;
    u16 t2    = (u16(rhs) & 0x07) << 13;
    tci_Set(parent, u16((tci_Get(parent) & ~t1) | t2));
}

// --- ietf.Vlanhdr.dei.Get
// Retrieve bitfield from value of field tci
//    1 bits starting at bit 12.
//    NOTE: bits correspond to the the integer value of the field.
//    The value is obtained by reading bytes from memory and swapping them.
inline u8 ietf::dei_Get(const ietf::Vlanhdr& parent) {
    return u8((tci_Get(parent) >> 12) & 0x01);
}

// --- ietf.Vlanhdr.dei.Set
// Set bitfield in value of field 'tci'
//    1 bits starting at bit 12.
//    NOTE: bits correspond to the integer value of 'tci'.
//    tci is stored in memory as big-endian.
//    The value is obtained by reading bytes from memory and swapping them.
inline void ietf::dei_Set(ietf::Vlanhdr& parent, u8 rhs) {
    u16 t1    = u16(0x01) << 12;
    u16 t2    = (u16(rhs) & 0x01) << 12;
    tci_Set(parent, u16((tci_Get(parent) & ~t1) | t2));
}

// --- ietf.Vlanhdr.vid.Get
// Retrieve bitfield from value of field tci
//    12 bits starting at bit 0.
//    NOTE: bits correspond to the the integer value of the field.
//    The value is obtained by reading bytes from memory and swapping them.
inline u16 ietf::vid_Get(const ietf::Vlanhdr& parent) {
    return u16((tci_Get(parent) >> 0) & 0xfff);
}

// --- ietf.Vlanhdr.vid.Set
// Set bitfield in value of field 'tci'
//    12 bits starting at bit 0.
//    NOTE: bits correspond to the integer value of 'tci'.
//    tci is stored in memory as big-endian.
//    The value is obtained by reading bytes from memory and swapping them.
inline void ietf::vid_Set(ietf::Vlanhdr& parent, u16 rhs) {
    u16 t1    = u16(0xfff) << 0;
    u16 t2    = (u16(rhs) & 0xfff) << 0;
    tci_Set(parent, u16((tci_Get(parent) & ~t1) | t2));
}

// --- ietf.Vlanhdr.ethertype.Get
inline u16 ietf::ethertype_Get(const ietf::Vlanhdr& parent) {
    return be16toh(parent.ethertype_be); // read big-endian value from memory
}

// --- ietf.Vlanhdr.ethertype.Set
inline void ietf::ethertype_Set(ietf::Vlanhdr& parent, u16 rhs) {
    parent.ethertype_be = htobe16(rhs); // write big-endian value to memory
}

// --- ietf.Vlanhdr..Init
// Set all fields to initial values.
inline void ietf::Vlanhdr_Init(ietf::Vlanhdr& parent) {
    parent.tci_be = htobe16(0); // write big-endian value to memory
    parent.ethertype_be = htobe16(0); // write big-endian value to memory
}

// --- ietf.Vlanhdr..Ctor
inline  ietf::Vlanhdr::Vlanhdr() {
    ietf::Vlanhdr_Init(*this);
}

